export type WorkshopFolder = keyof typeof workshopImages;
export type WorkshopImageKey<T extends WorkshopFolder> = keyof typeof workshopImages[T];

export const getWorkshopImage = (folder: string, imageKey: number | string, subfolder?: string): any => {
  const normalizedFolder = folder
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, "_")
    .replace(/[^a-zA-Z0-9_]/g, "_")
    .toUpperCase() as WorkshopFolder;

  const folderData = workshopImages[normalizedFolder];
  if (!folderData) return workshopImages.fallback;

  if (subfolder) {
    const normalizedSubfolder = subfolder
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/\s+/g, "_")
      .replace(/[^a-zA-Z0-9_]/g, "_")
      .toUpperCase();
    const subfolderData = (folderData as any)[normalizedSubfolder];
    if (!subfolderData) return workshopImages.fallback;
    return subfolderData[imageKey] ?? workshopImages.fallback;
  }

  return folderData[imageKey] ?? workshopImages.fallback;
};

export const getWorkshopImageCount = (folder: string, subfolder?: string): number => {
  const normalizedFolder = folder
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, "_")
    .replace(/[^a-zA-Z0-9_]/g, "_")
    .toUpperCase() as WorkshopFolder;

  const folderData = workshopImages[normalizedFolder];
  if (!folderData) return 0;

  if (subfolder) {
    const normalizedSubfolder = subfolder
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/\s+/g, "_")
      .replace(/[^a-zA-Z0-9_]/g, "_")
      .toUpperCase();
    const subfolderData = (folderData as any)[normalizedSubfolder];
    return subfolderData ? Object.keys(subfolderData).length : 0;
  }

  return Object.keys(folderData).filter(key => !isNaN(Number(key))).length;
};
